import { Clipboard, ClipboardModule } from '@angular/cdk/clipboard';
import { CommonModule } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { MatIconModule } from '@angular/material/icon';
import { MatMenuModule } from '@angular/material/menu';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { MatSlideToggleChange, MatSlideToggleModule } from '@angular/material/slide-toggle';
import { Router, RouterModule } from '@angular/router';
import { TranslocoModule } from '@jsverse/transloco';
import { requiresSmartEnrollSubscription } from 'app/core/client-settings/override-conditions';
import { AuthRequiredGateService } from 'app/core/services/auth-required-gate.service';
import { environment } from 'environments/environment';
import { DateTime } from 'luxon';
import { forkJoin, of } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { SmartEnrollPlansService } from '../../plans/smart-enroll-plans.service';
import {
    UsageQuotaPreviewComponent,
    type EnrollUsagePlanPreview,
} from '../../plans/usage-quota-preview.component';
import {
    PROJECT_SECURITY_DIALOG_PANEL_CLASS,
    ProjectSecurityModalComponent,
} from '../project-security-modal/project-security-modal.component';
import { SmartEnrollProjectsService } from '../smart-enroll-projects.service';
import type {
    EnrollProject,
    EnrollProjectFlow,
    EnrollProjectMember,
} from '../smart-enroll-projects.types';

@Component({
    selector: 'project-list',
    standalone: true,
    imports: [
        ClipboardModule,
        CommonModule,
        RouterModule,
        MatButtonModule,
        MatDialogModule,
        MatIconModule,
        MatMenuModule,
        MatProgressSpinnerModule,
        MatSlideToggleModule,
        TranslocoModule,
        UsageQuotaPreviewComponent,
    ],
    templateUrl: './project-list.component.html',
    styleUrls: ['./project-list.component.scss'],
})
export class ProjectListComponent implements OnInit {
    private _clipboard = inject(Clipboard);
    private _enrollPlansService = inject(SmartEnrollPlansService);
    private _projectsService = inject(SmartEnrollProjectsService);
    private _router = inject(Router);
    private _authGate = inject(AuthRequiredGateService);
    private _dialog = inject(MatDialog);
    projects = signal<EnrollProject[]>([]);
    loading = signal(true);
    error = signal<string | null>(null);
    noActivePlan = signal(false);
    activePlan = signal<EnrollUsagePlanPreview | null>(null);
    teaserPlan = signal<EnrollUsagePlanPreview | null>(null);

    ngOnInit(): void {
        this._authGate.runWithAuthOrDialog({
            onAuthenticated: () => this._loadProjectsAfterAuthGate(),
            panelClass: 'auth-required-dialog',
        });
    }

    private _loadProjectsAfterAuthGate(): void {
        const user = this._projectsService.parseStoredUser();
        if (user?.staff) {
            this._loadProjects();
            return;
        }
        forkJoin({
            plans: this._projectsService.getActiveSmartEnrollPlans(),
            settings: this._projectsService.getClientSettings(),
            catalog: this._enrollPlansService.getCatalogPlans().pipe(catchError(() => of({ data: [] }))),
        }).subscribe({
            next: ({ plans, settings, catalog }) => {
                const rows = plans?.data ?? [];
                this.activePlan.set((rows[0] as EnrollUsagePlanPreview) ?? null);

                if (!rows.length && requiresSmartEnrollSubscription(settings?.data)) {
                    this.teaserPlan.set(this._buildTeaserPlan(catalog?.data ?? []));
                    this.noActivePlan.set(true);
                    this.loading.set(false);
                    return;
                }

                this._loadProjects();
            },
            error: () => {
                this.error.set('smartEnrollProjects.plansLoadError');
                this.loading.set(false);
            },
        });
    }

    goToPlans(): void {
        this._router.navigate(['/smart-enroll/plans']);
    }

    /** Staff users cannot create workspace projects — list is scoped to assignments only. */
    isWorkspaceStaff(): boolean {
        return !!this._projectsService.parseStoredUser()?.staff;
    }

    /** Opens the Smart Enroll setup wizard (`/projects/new/setup/0`). */
    createProject(): void {
        this._router.navigate(['/smart-enroll/projects', 'new', 'setup', '0']);
    }

    openProject(project: EnrollProject, event?: Event): void {
        event?.stopPropagation();
        this._router.navigate(['/smart-enroll/projects', project._id]);
    }

    openRecords(project: EnrollProject, event?: Event): void {
        event?.stopPropagation();
        this._router.navigate(['/smart-enroll/projects', project._id, 'records']);
    }

    openStaff(project: EnrollProject, event?: Event): void {
        event?.stopPropagation();
        this._router.navigate(['/smart-enroll/projects', project._id, 'staff']);
    }

    openSecurityModal(project: EnrollProject, event?: Event): void {
        event?.stopPropagation();
        const ref = this._dialog.open(ProjectSecurityModalComponent, {
            data: { project },
            width: '600px',
            maxWidth: '90vw',
            disableClose: false,
            panelClass: PROJECT_SECURITY_DIALOG_PANEL_CLASS,
        });

        ref.afterClosed().subscribe((saved: boolean) => {
            if (saved) {
                this._loadProjects();
            }
        });
    }

    /**
     * Public Smart Enroll entry on the KYC / access host (`/sign-up/:projectId`), same as Verifik access app.
     */
    liveEnrollmentUrl(project: EnrollProject): string {
        const base = (environment.kycBaseUrl ?? '').replace(/\/+$/, '');
        return `${base}/sign-up/${project._id}`;
    }

    openLiveEnrollment(project: EnrollProject, event?: Event): void {
        event?.stopPropagation();
        const url = this.liveEnrollmentUrl(project);
        if (typeof window !== 'undefined') {
            window.open(url, '_blank', 'noopener,noreferrer');
        }
    }

    copyLiveEnrollmentUrl(project: EnrollProject, event?: Event): void {
        event?.stopPropagation();
        this._clipboard.copy(this.liveEnrollmentUrl(project));
    }

    openSection(project: EnrollProject, section: string, event: Event): void {
        event.stopPropagation();
        this._router.navigate(['/smart-enroll/projects', project._id], {
            queryParams: { section },
        });
    }

    membersForCard(project: EnrollProject): EnrollProjectMember[] {
        return (project.projectMembers ?? []).filter((m) => m.staff);
    }

    formatAcronym(name?: string): string {
        if (!name?.trim()) return '?';
        const matches = name.match(/\b(\w)/g);
        return matches?.slice(0, 2).join('').toUpperCase() ?? '?';
    }

    onFlowStatusToggle(event: MatSlideToggleChange, project: EnrollProject): void {
        const flow = this.currentFlow(project);
        if (!flow?._id) {
            event.source.checked = !event.source.checked;
            return;
        }
        const nextStatus = event.checked ? 'active' : 'draft';
        this._projectsService.updateProjectFlow(flow._id, { status: nextStatus }).subscribe({
            next: (res) => {
                const status = res?.data?.status ?? nextStatus;
                this.projects.update((list) =>
                    list.map((p) => {
                        if (p._id !== project._id) return p;
                        return {
                            ...p,
                            projectFlows:
                                p.projectFlows?.map((f) =>
                                    f._id === flow._id ? { ...f, status } : f
                                ) ?? [],
                        };
                    })
                );
            },
            error: () => {
                event.source.checked = !event.checked;
            },
        });
    }

    flowToggleChecked(flow: EnrollProjectFlow | null): boolean {
        return !!flow?.status && flow.status !== 'draft';
    }

    currentFlow(project: EnrollProject): EnrollProjectFlow | null {
        const flows = project.projectFlows;
        if (!flows?.length) return null;
        const active = flows.find((f) => f.status && f.status !== 'draft');
        return active ?? flows[0];
    }

    isDraftFlow(flow: EnrollProjectFlow | null): boolean {
        return !flow?.status || flow.status === 'draft';
    }

    formatUpdated(date?: string): string {
        if (!date) return '—';
        return DateTime.fromISO(date).toFormat('MMM dd, yyyy');
    }

    private _buildTeaserPlan(catalog: unknown[]): EnrollUsagePlanPreview {
        const rows = catalog as Array<{
            backgroundCheckLimit?: number;
            basicLimit?: number;
            code?: string;
            emailsLimit?: number;
            scanDocsLimit?: number;
            validateNamesLimit?: number;
        }>;
        const free = rows.find((row) => row?.code === 'smart_enroll_pyg');
        const enrolls = Number(free?.basicLimit) || 100;
        const scans = Number(free?.scanDocsLimit) || enrolls;

        return {
            backgroundCheckCount: 0,
            backgroundCheckLimit: Number(free?.backgroundCheckLimit) || 10,
            basicCount: 0,
            basicLimit: enrolls,
            biometricsLimit: 0,
            emailCount: 0,
            emailsLimit: Number(free?.emailsLimit) || 25,
            scanDocsCount: 0,
            scanDocsLimit: scans,
            validateNamesCount: 0,
            validateNamesLimit: Number(free?.validateNamesLimit) || 10,
        };
    }

    private _loadProjects(): void {
        this._projectsService.listProjects().subscribe({
            next: (list) => {
                this.projects.set(list);
                this.loading.set(false);
            },
            error: () => {
                this.error.set('smartEnrollProjects.loadError');
                this.loading.set(false);
            },
        });
    }
}
